      "审核时怎么问": "一、岗位专业问题：\n1. 你带过多大的团队？怎么分工和管理的？\n2. 怎么制定团队目标？怎么确保完成？\n3. 怎么招人？怎么判断人行不行？\n4. 团队有矛盾怎么办？怎么处理？\n\n二、行业验证问题：\n1. 广告/传媒/影视/文化/体育行业的管理有什么特点？\n2. 行业内哪家公司管理做得好？\n3. 管理岗的薪资大概是什么水平？\n4. 你觉得管理最难的是什么？",
      "能查到哪些证据": "【岗位能力证据】组织架构图、团队业绩数据、人员培养记录、管理体系文件、预算管理、跨部门项目成果、团队获奖证明。\n\n【行业经验证据】\n- 行业人脉和招聘渠道\n- 管理培训证书\n- 行业管理交流\n- 下属推荐和评价",
      "真干过的人怎么答": "【岗位专业表现】能负责一个部门或团队的全面管理，制定工作计划和目标，搭建团队体系和工作流程，有人员招聘和培养能力，能协调内外部资源，对业务结果负责，有成本和效益意识，关注团队成长和组织建设。\n\n【行业经验表现】\n1. 熟悉广告/传媒/影视/文化/体育行业的管理特点和人员结构\n2. 了解行业内的优秀企业管理模式\n3. 知道管理岗位的薪资范围和职业发展\n4. 有丰富的行业人脉和招聘渠道\n5. 对行业的发展和变化有深刻认识\n\n【管理特点】有制度流程建设能力，沟通协调能力强，服务意识好，细心严谨，原则性强，有保密意识。",
      "没干过的破绽": "【岗位能力破绽】只会管人事不会管业务、团队业绩差、人才培养能力弱、只会上传下达没有自己的思路、部门协作能力差。\n\n【行业经验破绽】\n1. 不了解广告/传媒/影视/文化/体育行业的管理特点\n2. 说不出具体的管理方法和体系\n3. 没有招聘渠道和人才资源\n4. 对行业管理趋势不关注\n\n【管理破绽】沟通协调差、不细心、原则性弱、服务意识差、保密意识淡薄。",
      "审批要点": "【岗位核心能力】团队管理、目标管理、人才获取、沟通协调、业务理解、领导力。\n\n【行业适配性】是否有广告/传媒/影视/文化/体育行业管理经验、能否适应行业特点、管理风格是否匹配、抗压能力如何。\n\n【风险提示】管理岗最容易包装，需要核实真实团队规模和业绩；很多\"经理\"只是个小组长；要区分\"真管理\"和\"假管理\"；管理风格比管理经验更重要。",
